            internal bool AnyCustomCost()
            {
                foreach (var options in Custom.Values)
                {
                    foreach (var option in options)
                    {
                        if (option.isItem || option.isPlugin)
                        {
                            return true;
                        }
                    }
                }
                return false;
            }
        }

