                    return TeleportUiCreated && TeleportShowMoveButton == showMoveButton && TeleportMode == mode && TeleportOffsetMin == offsets.Min && TeleportOffsetMax == offsets.Max && TeleportNormalizedAnchor == offsets.NormalizedAnchor;
                }

