                internal void SetTeleportPosition(UiOffsets offsets)
                {
                    TeleportOffsetMin = offsets.Min;
                    TeleportOffsetMax = offsets.Max;
                    TeleportNormalizedAnchor = offsets.NormalizedAnchor;
